	protected CreateRoomCommand generateNewCommand() {
        CreateRoomCommand command = new CreateRoomCommand( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16) );
		
		return( command );
	}

		/**
		 * Returns a new populated Room
		 * 
		 * @return UpdateRoomCommand alias
		 */
	protected UpdateRoomCommand generateUpdateCommand() {
	        UpdateRoomCommand command = new UpdateRoomCommand( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  null,  new HashSet<>(),  new HashSet<>() );
			
			return( command );
		}
